before:
Complete local Rust example; the app itself does not execute it:
```rust


fn main() {
    let input = ["15", "bad", "0", "20"];
    let accepted: Vec<u32> = input.into_iter()
        .filter_map(|text| text.parse::<u32>().ok())
        .filter(|n| (1..=60).contains(n))
        .take(2).collect();
    println!("{accepted:?}");
    println!("{}", accepted.iter().sum::<u32>());
}
```

